const providerInfo = {"id":"simple-icons","name":"Simple Icons","version":"16.28.0","source":"https://github.com/simple-icons/simple-icons"};
export { icons, providerInfo };
export function getIcon(name) { return icons[name]; }
export function hasIcon(name) { return Object.prototype.hasOwnProperty.call(icons, name); }
export function searchIcons(query) { const q = String(query ?? "").trim().toLowerCase(); return Object.values(icons).filter((icon) => !q || [icon.name, icon.label, ...(icon.aliases || []), ...(icon.tags || [])].join(" ").toLowerCase().includes(q)); }
